CREATE TABLE IF NOT EXISTS "athletes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle used in profile URLs. Compared case-insensitively so two athletes cannot differ only by capitalisation.
	"username" VARCHAR(40) NOT NULL UNIQUE,
	-- Name shown on leaderboards and activity feeds.
	"display_name" VARCHAR(120) NOT NULL,
	-- Login identity.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- ISO 3166-1 country, used for regional leaderboard filters.
	"country_code" CHAR(2),
	-- Body mass in grams. Integer because power-to-weight ratios are computed from it and floats drift; null when the athlete has not entered one.
	"weight_grams" INTEGER,
	-- Functional threshold power, the anchor for cycling training load. Null for athletes who have never tested.
	"ftp_watts" SMALLINT,
	-- Used to scale heart-rate-based effort scores.
	"resting_heart_rate" SMALLINT,
	-- metric | imperial. A display preference only — everything is stored in SI units.
	"measurement_preference" VARCHAR(8) NOT NULL DEFAULT 'metric',
	-- public | followers | private. The default applied to new activities, not a retroactive setting.
	"default_activity_visibility" VARCHAR(16) NOT NULL DEFAULT 'followers',
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "athletes" IS 'The account and the athlete profile in one row. Physiological fields live here rather than in a settings blob because training load calculations read them on every upload.';
COMMENT ON COLUMN "athletes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "athletes"."username" IS 'Public handle used in profile URLs. Compared case-insensitively so two athletes cannot differ only by capitalisation.';
COMMENT ON COLUMN "athletes"."display_name" IS 'Name shown on leaderboards and activity feeds.';
COMMENT ON COLUMN "athletes"."email" IS 'Login identity.';
COMMENT ON COLUMN "athletes"."country_code" IS 'ISO 3166-1 country, used for regional leaderboard filters.';
COMMENT ON COLUMN "athletes"."weight_grams" IS 'Body mass in grams. Integer because power-to-weight ratios are computed from it and floats drift; null when the athlete has not entered one.';
COMMENT ON COLUMN "athletes"."ftp_watts" IS 'Functional threshold power, the anchor for cycling training load. Null for athletes who have never tested.';
COMMENT ON COLUMN "athletes"."resting_heart_rate" IS 'Used to scale heart-rate-based effort scores.';
COMMENT ON COLUMN "athletes"."measurement_preference" IS 'metric | imperial. A display preference only — everything is stored in SI units.';
COMMENT ON COLUMN "athletes"."default_activity_visibility" IS 'public | followers | private. The default applied to new activities, not a retroactive setting.';
COMMENT ON COLUMN "athletes"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "gear" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner. Gear is personal, so there is no shared catalogue.
	"athlete_id" BIGINT NOT NULL,
	-- bike | shoes. Decides which activity types may be tagged with it.
	"gear_type" VARCHAR(16) NOT NULL,
	-- What the athlete calls it, e.g. Winter bike.
	"name" VARCHAR(120) NOT NULL,
	-- Manufacturer, for the gear report.
	"brand" VARCHAR(80),
	-- Cumulative distance, maintained as a running total on upload. Summing activities on every profile view would be a table scan of the largest table in the schema.
	"distance_metres" BIGINT NOT NULL DEFAULT 0,
	-- Purchase date, so wear can be expressed per month as well as per kilometre.
	"purchased_on" DATE,
	-- When it was retired. Null while in use; retired gear stays because past activities still reference it.
	"retired_at" TIMESTAMPTZ,
	-- Pre-selected for new activities of the matching type.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "gear" IS 'Bikes and shoes, with a denormalised mileage counter. The counter is the point: replacing a chain or a pair of shoes is a decision made on accumulated distance, and that number has to be cheap to read.';
COMMENT ON COLUMN "gear"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "gear"."athlete_id" IS 'Owner. Gear is personal, so there is no shared catalogue.';
COMMENT ON COLUMN "gear"."gear_type" IS 'bike | shoes. Decides which activity types may be tagged with it.';
COMMENT ON COLUMN "gear"."name" IS 'What the athlete calls it, e.g. Winter bike.';
COMMENT ON COLUMN "gear"."brand" IS 'Manufacturer, for the gear report.';
COMMENT ON COLUMN "gear"."distance_metres" IS 'Cumulative distance, maintained as a running total on upload. Summing activities on every profile view would be a table scan of the largest table in the schema.';
COMMENT ON COLUMN "gear"."purchased_on" IS 'Purchase date, so wear can be expressed per month as well as per kilometre.';
COMMENT ON COLUMN "gear"."retired_at" IS 'When it was retired. Null while in use; retired gear stays because past activities still reference it.';
COMMENT ON COLUMN "gear"."is_default" IS 'Pre-selected for new activities of the matching type.';

CREATE INDEX "idx_gear_athlete_type"
ON "gear" ("athlete_id", "gear_type");

CREATE TABLE IF NOT EXISTS "activities" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Athlete who recorded it.
	"athlete_id" BIGINT NOT NULL,
	-- Bike or shoes used. Null when untagged or when the gear was deleted before retirement was introduced.
	"gear_id" BIGINT,
	-- run | ride | swim | hike | walk | workout. Leaderboards, records and training load all branch on this.
	"sport_type" VARCHAR(24) NOT NULL,
	-- Athlete-supplied name, defaulted from time of day on upload.
	"title" VARCHAR(160) NOT NULL,
	-- Free-text write-up shown under the activity.
	"description" TEXT,
	-- Start instant in UTC.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- IANA zone at the start location. Stored alongside the instant because Morning Run is a local-time concept and a trip abroad must not relabel it.
	"local_timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Wall-clock duration including stops.
	"elapsed_seconds" INTEGER NOT NULL,
	-- Duration excluding auto-pause. Kept separately because pace is computed from moving time while a race result uses elapsed.
	"moving_seconds" INTEGER NOT NULL,
	-- Total distance in metres. Integer metres are precise enough for any display and sort correctly.
	"distance_metres" INTEGER NOT NULL DEFAULT 0,
	-- Summed positive elevation, already smoothed on ingest — raw barometric noise would inflate it by tens of percent.
	"elevation_gain_metres" INTEGER NOT NULL DEFAULT 0,
	-- Mean power. Null when no power meter was present.
	"average_watts" SMALLINT,
	-- Mean heart rate. Null when unmonitored.
	"average_heart_rate" SMALLINT,
	-- Estimated energy expenditure.
	"calories" INTEGER,
	-- public | followers | private. Snapshotted from the athlete default at upload so changing the default does not silently expose old activities.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'followers',
	-- Recording device, useful when diagnosing a suspicious GPS trace.
	"device_name" VARCHAR(120),
	-- True for hand-entered activities with no file. Manual activities are excluded from leaderboards because there is nothing to verify.
	"is_manual" BOOLEAN NOT NULL DEFAULT false,
	-- Set when the community or an automated check disputes the data. Flagged activities are hidden from leaderboards without being deleted.
	"is_flagged" BOOLEAN NOT NULL DEFAULT false,
	-- Ingest time, which can be days after started_at.
	"uploaded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "activities" IS 'One recorded workout and the summary everything else reads. Every aggregate here is computed once on ingest, because the alternative is recomputing it from millions of sensor samples each time a feed renders.';
COMMENT ON COLUMN "activities"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "activities"."athlete_id" IS 'Athlete who recorded it.';
COMMENT ON COLUMN "activities"."gear_id" IS 'Bike or shoes used. Null when untagged or when the gear was deleted before retirement was introduced.';
COMMENT ON COLUMN "activities"."sport_type" IS 'run | ride | swim | hike | walk | workout. Leaderboards, records and training load all branch on this.';
COMMENT ON COLUMN "activities"."title" IS 'Athlete-supplied name, defaulted from time of day on upload.';
COMMENT ON COLUMN "activities"."description" IS 'Free-text write-up shown under the activity.';
COMMENT ON COLUMN "activities"."started_at" IS 'Start instant in UTC.';
COMMENT ON COLUMN "activities"."local_timezone" IS 'IANA zone at the start location. Stored alongside the instant because Morning Run is a local-time concept and a trip abroad must not relabel it.';
COMMENT ON COLUMN "activities"."elapsed_seconds" IS 'Wall-clock duration including stops.';
COMMENT ON COLUMN "activities"."moving_seconds" IS 'Duration excluding auto-pause. Kept separately because pace is computed from moving time while a race result uses elapsed.';
COMMENT ON COLUMN "activities"."distance_metres" IS 'Total distance in metres. Integer metres are precise enough for any display and sort correctly.';
COMMENT ON COLUMN "activities"."elevation_gain_metres" IS 'Summed positive elevation, already smoothed on ingest — raw barometric noise would inflate it by tens of percent.';
COMMENT ON COLUMN "activities"."average_watts" IS 'Mean power. Null when no power meter was present.';
COMMENT ON COLUMN "activities"."average_heart_rate" IS 'Mean heart rate. Null when unmonitored.';
COMMENT ON COLUMN "activities"."calories" IS 'Estimated energy expenditure.';
COMMENT ON COLUMN "activities"."visibility" IS 'public | followers | private. Snapshotted from the athlete default at upload so changing the default does not silently expose old activities.';
COMMENT ON COLUMN "activities"."device_name" IS 'Recording device, useful when diagnosing a suspicious GPS trace.';
COMMENT ON COLUMN "activities"."is_manual" IS 'True for hand-entered activities with no file. Manual activities are excluded from leaderboards because there is nothing to verify.';
COMMENT ON COLUMN "activities"."is_flagged" IS 'Set when the community or an automated check disputes the data. Flagged activities are hidden from leaderboards without being deleted.';
COMMENT ON COLUMN "activities"."uploaded_at" IS 'Ingest time, which can be days after started_at.';

CREATE INDEX "idx_activities_athlete_started"
ON "activities" ("athlete_id", "started_at");
CREATE INDEX "idx_activities_sport_started"
ON "activities" ("sport_type", "started_at");

CREATE TABLE IF NOT EXISTS "activity_streams" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Activity the stream belongs to.
	"activity_id" BIGINT NOT NULL,
	-- time | latlng | altitude | heartrate | watts | cadence | temperature. One row per channel per activity.
	"stream_type" VARCHAR(20) NOT NULL,
	-- Number of samples in the blob. Stored so a consumer can size buffers without decoding.
	"sample_count" INTEGER NOT NULL,
	-- Nominal sampling period, usually 1. Null for irregularly sampled channels where the time stream carries the offsets.
	"sample_interval_seconds" SMALLINT,
	-- How the blob is packed. Recorded per row so the format can change without rewriting history.
	"encoding" VARCHAR(24) NOT NULL DEFAULT 'delta-zigzag-gzip',
	-- Divisor applied after decoding to recover the physical unit, e.g. 10 for tenths of a metre. Keeps the packed integers small.
	"scale_factor" INTEGER NOT NULL DEFAULT 1,
	-- The samples, delta-encoded and compressed. A four-hour ride at one hertz is roughly fourteen thousand values per channel; as a blob it is a few kilobytes and one read.
	"data" BYTEA NOT NULL,
	-- Stored size, used to bill storage and to spot pathological files.
	"compressed_bytes" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "activity_streams" IS 'Sensor time series, one row per channel rather than one row per sample. A row per second would turn a single long ride into six figures of rows, and nothing in the product ever queries an individual sample — streams are fetched whole to draw a chart or recompute an effort.';
COMMENT ON COLUMN "activity_streams"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "activity_streams"."activity_id" IS 'Activity the stream belongs to.';
COMMENT ON COLUMN "activity_streams"."stream_type" IS 'time | latlng | altitude | heartrate | watts | cadence | temperature. One row per channel per activity.';
COMMENT ON COLUMN "activity_streams"."sample_count" IS 'Number of samples in the blob. Stored so a consumer can size buffers without decoding.';
COMMENT ON COLUMN "activity_streams"."sample_interval_seconds" IS 'Nominal sampling period, usually 1. Null for irregularly sampled channels where the time stream carries the offsets.';
COMMENT ON COLUMN "activity_streams"."encoding" IS 'How the blob is packed. Recorded per row so the format can change without rewriting history.';
COMMENT ON COLUMN "activity_streams"."scale_factor" IS 'Divisor applied after decoding to recover the physical unit, e.g. 10 for tenths of a metre. Keeps the packed integers small.';
COMMENT ON COLUMN "activity_streams"."data" IS 'The samples, delta-encoded and compressed. A four-hour ride at one hertz is roughly fourteen thousand values per channel; as a blob it is a few kilobytes and one read.';
COMMENT ON COLUMN "activity_streams"."compressed_bytes" IS 'Stored size, used to bill storage and to spot pathological files.';

CREATE UNIQUE INDEX "uq_stream_activity_type"
ON "activity_streams" ("activity_id", "stream_type");

CREATE TABLE IF NOT EXISTS "segments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Athlete who defined it. Null for segments imported in bulk.
	"created_by_athlete_id" BIGINT,
	-- What the climb or sprint is called locally.
	"name" VARCHAR(160) NOT NULL,
	-- run | ride | swim. A running segment and a riding segment over the same road are different competitions and different leaderboards.
	"sport_type" VARCHAR(24) NOT NULL,
	-- Segment length, the denominator of every pace and speed on the leaderboard.
	"distance_metres" INTEGER NOT NULL,
	-- Mean gradient. Signed, because a descent segment is a different kind of effort.
	"average_grade_percent" DECIMAL(5,2) NOT NULL DEFAULT 0,
	-- Total climbing over the segment.
	"elevation_gain_metres" INTEGER NOT NULL DEFAULT 0,
	-- Start point latitude. Six decimal places resolve to about a tenth of a metre, which is finer than consumer GPS.
	"start_latitude" DECIMAL(9,6) NOT NULL,
	-- Start point longitude.
	"start_longitude" DECIMAL(9,6) NOT NULL,
	-- End point latitude.
	"end_latitude" DECIMAL(9,6) NOT NULL,
	-- End point longitude.
	"end_longitude" DECIMAL(9,6) NOT NULL,
	-- Encoded path used for map rendering and for matching an uploaded trace against the segment.
	"polyline" TEXT NOT NULL,
	-- Nearest place name, for browse and search.
	"city" VARCHAR(120),
	-- Marks a segment whose leaderboard is hidden because racing it is dangerous, typically a descent.
	"is_hazardous" BOOLEAN NOT NULL DEFAULT false,
	-- Visible only to the creator, used for segments across private property.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Cached number of efforts, so a popularity sort does not count a huge child table.
	"effort_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "segments" IS 'A named stretch of road or trail that people race. Segments are defined independently of any activity, which is what lets an effort recorded years later be compared with one from the day the segment was created.';
COMMENT ON COLUMN "segments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "segments"."created_by_athlete_id" IS 'Athlete who defined it. Null for segments imported in bulk.';
COMMENT ON COLUMN "segments"."name" IS 'What the climb or sprint is called locally.';
COMMENT ON COLUMN "segments"."sport_type" IS 'run | ride | swim. A running segment and a riding segment over the same road are different competitions and different leaderboards.';
COMMENT ON COLUMN "segments"."distance_metres" IS 'Segment length, the denominator of every pace and speed on the leaderboard.';
COMMENT ON COLUMN "segments"."average_grade_percent" IS 'Mean gradient. Signed, because a descent segment is a different kind of effort.';
COMMENT ON COLUMN "segments"."elevation_gain_metres" IS 'Total climbing over the segment.';
COMMENT ON COLUMN "segments"."start_latitude" IS 'Start point latitude. Six decimal places resolve to about a tenth of a metre, which is finer than consumer GPS.';
COMMENT ON COLUMN "segments"."start_longitude" IS 'Start point longitude.';
COMMENT ON COLUMN "segments"."end_latitude" IS 'End point latitude.';
COMMENT ON COLUMN "segments"."end_longitude" IS 'End point longitude.';
COMMENT ON COLUMN "segments"."polyline" IS 'Encoded path used for map rendering and for matching an uploaded trace against the segment.';
COMMENT ON COLUMN "segments"."city" IS 'Nearest place name, for browse and search.';
COMMENT ON COLUMN "segments"."is_hazardous" IS 'Marks a segment whose leaderboard is hidden because racing it is dangerous, typically a descent.';
COMMENT ON COLUMN "segments"."is_private" IS 'Visible only to the creator, used for segments across private property.';
COMMENT ON COLUMN "segments"."effort_count" IS 'Cached number of efforts, so a popularity sort does not count a huge child table.';
COMMENT ON COLUMN "segments"."created_at" IS 'Creation time.';

CREATE INDEX "idx_segments_start_point"
ON "segments" ("start_latitude", "start_longitude");
CREATE INDEX "idx_segments_sport_popularity"
ON "segments" ("sport_type", "effort_count");

CREATE TABLE IF NOT EXISTS "segment_efforts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Segment attempted.
	"segment_id" BIGINT NOT NULL,
	-- Activity the effort was extracted from. Deleting the activity deletes the effort — an effort with no trace behind it is unverifiable.
	"activity_id" BIGINT NOT NULL,
	-- Athlete who rode or ran it. Denormalised from the activity because every leaderboard query filters or groups on it.
	"athlete_id" BIGINT NOT NULL,
	-- When the athlete crossed the start of the segment.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- Time from segment start to segment end. The leaderboard sort key, and the only number that decides the ranking.
	"elapsed_seconds" INTEGER NOT NULL,
	-- Time excluding stops, shown but never ranked on — stopping at a junction is part of the effort.
	"moving_seconds" INTEGER,
	-- Mean power over the segment, if recorded.
	"average_watts" SMALLINT,
	-- Mean heart rate over the segment.
	"average_heart_rate" SMALLINT,
	-- True for the athlete fastest surviving effort on this segment. Maintained on write so a profile does not have to sort every effort the athlete ever made.
	"is_personal_best" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "segment_efforts" IS 'One attempt at one segment, extracted from an activity on upload. This is the largest table in the schema and the one the product is built on: a popular climb accumulates millions of rows, and the index on (segment_id, elapsed_seconds) is what makes the all-time leaderboard an index scan of the first hundred entries.';
COMMENT ON COLUMN "segment_efforts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "segment_efforts"."segment_id" IS 'Segment attempted.';
COMMENT ON COLUMN "segment_efforts"."activity_id" IS 'Activity the effort was extracted from. Deleting the activity deletes the effort — an effort with no trace behind it is unverifiable.';
COMMENT ON COLUMN "segment_efforts"."athlete_id" IS 'Athlete who rode or ran it. Denormalised from the activity because every leaderboard query filters or groups on it.';
COMMENT ON COLUMN "segment_efforts"."started_at" IS 'When the athlete crossed the start of the segment.';
COMMENT ON COLUMN "segment_efforts"."elapsed_seconds" IS 'Time from segment start to segment end. The leaderboard sort key, and the only number that decides the ranking.';
COMMENT ON COLUMN "segment_efforts"."moving_seconds" IS 'Time excluding stops, shown but never ranked on — stopping at a junction is part of the effort.';
COMMENT ON COLUMN "segment_efforts"."average_watts" IS 'Mean power over the segment, if recorded.';
COMMENT ON COLUMN "segment_efforts"."average_heart_rate" IS 'Mean heart rate over the segment.';
COMMENT ON COLUMN "segment_efforts"."is_personal_best" IS 'True for the athlete fastest surviving effort on this segment. Maintained on write so a profile does not have to sort every effort the athlete ever made.';

CREATE INDEX "idx_efforts_segment_time"
ON "segment_efforts" ("segment_id", "elapsed_seconds");
CREATE INDEX "idx_efforts_athlete_segment_time"
ON "segment_efforts" ("athlete_id", "segment_id", "elapsed_seconds");
CREATE INDEX "idx_efforts_activity"
ON "segment_efforts" ("activity_id");

CREATE TABLE IF NOT EXISTS "segment_leaderboard_entries" (
	-- Segment the ranking belongs to. Composite key with athlete_id.
	"segment_id" BIGINT,
	-- Athlete ranked. One row per athlete per segment is what the leaderboard actually shows.
	"athlete_id" BIGINT,
	-- The effort that earned the position, so the leaderboard links straight to the ride it came from.
	"best_effort_id" BIGINT NOT NULL,
	-- The winning time, duplicated from the effort so the leaderboard never has to join to rank.
	"elapsed_seconds" INTEGER NOT NULL,
	-- When the best effort happened. Breaks ties in favour of whoever did it first.
	"achieved_at" TIMESTAMPTZ NOT NULL,
	-- How many times this athlete has attempted the segment, shown next to their name.
	"effort_count" INTEGER NOT NULL DEFAULT 1,
	-- Last recomputation, which happens when a faster effort lands or the previous best is deleted.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("segment_id", "athlete_id")
);

COMMENT ON TABLE "segment_leaderboard_entries" IS 'The materialised leaderboard: best effort per athlete per segment. A leaderboard is not the fastest efforts, it is the fastest athletes — deriving that from segment_efforts means a DISTINCT ON over millions of rows per page view, so the answer is maintained on write instead.';
COMMENT ON COLUMN "segment_leaderboard_entries"."segment_id" IS 'Segment the ranking belongs to. Composite key with athlete_id.';
COMMENT ON COLUMN "segment_leaderboard_entries"."athlete_id" IS 'Athlete ranked. One row per athlete per segment is what the leaderboard actually shows.';
COMMENT ON COLUMN "segment_leaderboard_entries"."best_effort_id" IS 'The effort that earned the position, so the leaderboard links straight to the ride it came from.';
COMMENT ON COLUMN "segment_leaderboard_entries"."elapsed_seconds" IS 'The winning time, duplicated from the effort so the leaderboard never has to join to rank.';
COMMENT ON COLUMN "segment_leaderboard_entries"."achieved_at" IS 'When the best effort happened. Breaks ties in favour of whoever did it first.';
COMMENT ON COLUMN "segment_leaderboard_entries"."effort_count" IS 'How many times this athlete has attempted the segment, shown next to their name.';
COMMENT ON COLUMN "segment_leaderboard_entries"."updated_at" IS 'Last recomputation, which happens when a faster effort lands or the previous best is deleted.';

CREATE INDEX "idx_leaderboard_segment_rank"
ON "segment_leaderboard_entries" ("segment_id", "elapsed_seconds");

CREATE TABLE IF NOT EXISTS "personal_records" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Record holder.
	"athlete_id" BIGINT NOT NULL,
	-- Sport the record belongs to. A best 5k running time and a best 5k on a bike are unrelated.
	"sport_type" VARCHAR(24) NOT NULL,
	-- fastest_1k | fastest_5k | fastest_10k | longest_distance | biggest_climb | best_20min_power.
	"record_type" VARCHAR(40) NOT NULL,
	-- Activity that set it, so the record links to the effort behind it.
	"activity_id" BIGINT NOT NULL,
	-- The record value, in the unit named by value_unit. Numeric rather than float because records are compared for equality and displayed to three decimals.
	"value_numeric" DECIMAL(12,3) NOT NULL,
	-- seconds | metres | watts. Stored per row because one table holds records of different kinds.
	"value_unit" VARCHAR(16) NOT NULL,
	-- Local date of the record, which is what an athlete remembers it by.
	"achieved_on" DATE NOT NULL,
	-- False once beaten. Superseded records are kept so a profile can show progression rather than only the current best.
	"is_current" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "personal_records" IS 'Bests across distances and durations, derived from streams on upload. Records are rows rather than columns on the athlete because the set of record types grows, and because progression over time is the interesting view.';
COMMENT ON COLUMN "personal_records"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "personal_records"."athlete_id" IS 'Record holder.';
COMMENT ON COLUMN "personal_records"."sport_type" IS 'Sport the record belongs to. A best 5k running time and a best 5k on a bike are unrelated.';
COMMENT ON COLUMN "personal_records"."record_type" IS 'fastest_1k | fastest_5k | fastest_10k | longest_distance | biggest_climb | best_20min_power.';
COMMENT ON COLUMN "personal_records"."activity_id" IS 'Activity that set it, so the record links to the effort behind it.';
COMMENT ON COLUMN "personal_records"."value_numeric" IS 'The record value, in the unit named by value_unit. Numeric rather than float because records are compared for equality and displayed to three decimals.';
COMMENT ON COLUMN "personal_records"."value_unit" IS 'seconds | metres | watts. Stored per row because one table holds records of different kinds.';
COMMENT ON COLUMN "personal_records"."achieved_on" IS 'Local date of the record, which is what an athlete remembers it by.';
COMMENT ON COLUMN "personal_records"."is_current" IS 'False once beaten. Superseded records are kept so a profile can show progression rather than only the current best.';

CREATE INDEX "idx_records_athlete_type_current"
ON "personal_records" ("athlete_id", "record_type", "is_current");

CREATE TABLE IF NOT EXISTS "kudos" (
	-- Activity being praised. Composite key with athlete_id.
	"activity_id" BIGINT,
	-- Athlete giving kudos. The composite primary key is the uniqueness rule: one kudos per athlete per activity, enforced by the table shape rather than by application code.
	"athlete_id" BIGINT,
	-- When it was given, used to order the notification feed.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("activity_id", "athlete_id")
);

COMMENT ON TABLE "kudos" IS 'The lightest possible interaction, so it gets the lightest possible table: two foreign keys and a timestamp, no surrogate id. Un-kudos is a delete, and the counter shown on the activity is maintained separately rather than counted per render.';
COMMENT ON COLUMN "kudos"."activity_id" IS 'Activity being praised. Composite key with athlete_id.';
COMMENT ON COLUMN "kudos"."athlete_id" IS 'Athlete giving kudos. The composite primary key is the uniqueness rule: one kudos per athlete per activity, enforced by the table shape rather than by application code.';
COMMENT ON COLUMN "kudos"."created_at" IS 'When it was given, used to order the notification feed.';

CREATE INDEX "idx_kudos_athlete_time"
ON "kudos" ("athlete_id", "created_at");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Activity commented on.
	"activity_id" BIGINT NOT NULL,
	-- Author.
	"athlete_id" BIGINT NOT NULL,
	-- Comment text. Bounded because this is a caption box, not a forum post.
	"body" VARCHAR(1000) NOT NULL,
	-- Post time, the feed ordering key.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last edit. Null when never edited, which is what lets the UI show an edited marker honestly.
	"edited_at" TIMESTAMPTZ,
	-- Soft delete, so replies and notifications referencing the comment do not dangle.
	"is_deleted" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Conversation on an activity. Soft-deleted rather than removed because a deleted comment still has to disappear from a notification that already went out.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."activity_id" IS 'Activity commented on.';
COMMENT ON COLUMN "comments"."athlete_id" IS 'Author.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text. Bounded because this is a caption box, not a forum post.';
COMMENT ON COLUMN "comments"."created_at" IS 'Post time, the feed ordering key.';
COMMENT ON COLUMN "comments"."edited_at" IS 'Last edit. Null when never edited, which is what lets the UI show an edited marker honestly.';
COMMENT ON COLUMN "comments"."is_deleted" IS 'Soft delete, so replies and notifications referencing the comment do not dangle.';

CREATE INDEX "idx_comments_activity_time"
ON "comments" ("activity_id", "created_at");

CREATE TABLE IF NOT EXISTS "clubs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Club name.
	"name" VARCHAR(160) NOT NULL,
	-- URL identifier, immutable once issued so shared links keep working after a rename.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Primary sport. Null for multi-sport clubs.
	"sport_type" VARCHAR(24),
	-- Where it meets, for discovery.
	"city" VARCHAR(120),
	-- Private clubs require approval, which is why membership carries a status rather than just a join date.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Cached membership size for listings. Counting members per card in a directory is the query that takes a club page down.
	"member_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "clubs" IS 'A group athletes join, with its own leaderboards and challenges. Clubs own no activities — they are a lens over their members activities, which keeps a departure from erasing history.';
COMMENT ON COLUMN "clubs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "clubs"."name" IS 'Club name.';
COMMENT ON COLUMN "clubs"."slug" IS 'URL identifier, immutable once issued so shared links keep working after a rename.';
COMMENT ON COLUMN "clubs"."sport_type" IS 'Primary sport. Null for multi-sport clubs.';
COMMENT ON COLUMN "clubs"."city" IS 'Where it meets, for discovery.';
COMMENT ON COLUMN "clubs"."is_private" IS 'Private clubs require approval, which is why membership carries a status rather than just a join date.';
COMMENT ON COLUMN "clubs"."member_count" IS 'Cached membership size for listings. Counting members per card in a directory is the query that takes a club page down.';
COMMENT ON COLUMN "clubs"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "club_memberships" (
	-- Club joined. Composite key with athlete_id.
	"club_id" BIGINT,
	-- Member. Composite primary key means an athlete cannot hold two memberships of the same club.
	"athlete_id" BIGINT,
	-- member | admin | owner. Owners cannot be removed by admins.
	"role" VARCHAR(16) NOT NULL DEFAULT 'member',
	-- pending | active | banned. Pending is the queue for private clubs; banned is kept so a rejoin can be refused.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When the membership began, used for seniority and for club-since badges.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("club_id", "athlete_id")
);

COMMENT ON TABLE "club_memberships" IS 'Join table between athletes and clubs with a composite key and no surrogate id. Status lives here rather than as a separate invitations table because a pending request and a membership are the same relationship at different stages.';
COMMENT ON COLUMN "club_memberships"."club_id" IS 'Club joined. Composite key with athlete_id.';
COMMENT ON COLUMN "club_memberships"."athlete_id" IS 'Member. Composite primary key means an athlete cannot hold two memberships of the same club.';
COMMENT ON COLUMN "club_memberships"."role" IS 'member | admin | owner. Owners cannot be removed by admins.';
COMMENT ON COLUMN "club_memberships"."status" IS 'pending | active | banned. Pending is the queue for private clubs; banned is kept so a rejoin can be refused.';
COMMENT ON COLUMN "club_memberships"."joined_at" IS 'When the membership began, used for seniority and for club-since badges.';

CREATE INDEX "idx_memberships_athlete_status"
ON "club_memberships" ("athlete_id", "status");

CREATE TABLE IF NOT EXISTS "training_load_days" (
	-- Athlete the day belongs to. Composite key with load_date.
	"athlete_id" BIGINT,
	-- Local calendar date. Composite primary key gives exactly one row per athlete per day, including rest days, which is what makes the series continuous.
	"load_date" DATE,
	-- Stress score for the day, summed across activities. Zero on a rest day, and that zero matters — a gap would be interpolated by the chart.
	"training_load" SMALLINT NOT NULL DEFAULT 0,
	-- Long-term exponentially weighted average of training load. Recomputed forward from the day an activity is added or deleted.
	"fitness" DECIMAL(6,2) NOT NULL DEFAULT 0,
	-- Short-term weighted average of the same series.
	"fatigue" DECIMAL(6,2) NOT NULL DEFAULT 0,
	-- Fitness minus fatigue. Stored rather than computed on read so the chart is a single range scan.
	"form" DECIMAL(6,2) NOT NULL DEFAULT 0,
	-- How many activities contributed, so a zero-load day with a recorded walk is distinguishable from a true rest day.
	"activity_count" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("athlete_id", "load_date")
);

COMMENT ON TABLE "training_load_days" IS 'One row per athlete per day, rest days included. Training load is a recursive series where each day depends on the one before, so it is materialised daily rather than derived at read time — and the deliberate zero rows are what keep the recursion honest.';
COMMENT ON COLUMN "training_load_days"."athlete_id" IS 'Athlete the day belongs to. Composite key with load_date.';
COMMENT ON COLUMN "training_load_days"."load_date" IS 'Local calendar date. Composite primary key gives exactly one row per athlete per day, including rest days, which is what makes the series continuous.';
COMMENT ON COLUMN "training_load_days"."training_load" IS 'Stress score for the day, summed across activities. Zero on a rest day, and that zero matters — a gap would be interpolated by the chart.';
COMMENT ON COLUMN "training_load_days"."fitness" IS 'Long-term exponentially weighted average of training load. Recomputed forward from the day an activity is added or deleted.';
COMMENT ON COLUMN "training_load_days"."fatigue" IS 'Short-term weighted average of the same series.';
COMMENT ON COLUMN "training_load_days"."form" IS 'Fitness minus fatigue. Stored rather than computed on read so the chart is a single range scan.';
COMMENT ON COLUMN "training_load_days"."activity_count" IS 'How many activities contributed, so a zero-load day with a recorded walk is distinguishable from a true rest day.';

CREATE INDEX "idx_load_athlete_date"
ON "training_load_days" ("athlete_id", "load_date");

